'use strict';

/*
  Training Frontend Module
  - โมดูลข้อมูลอบรม/ดูงานและชั่วโมงอบรม
  - จัดการรายการ เพิ่ม/แก้ไข/ลบ และส่งข้อมูลไป backend action ของ training
  - ช่องวันที่ควรใช้ Thai date picker/format เดียวกับระบบหลัก
*/

const TRAINING_CONFIG = {
  API_URL: (window.MIS_CONFIG && window.MIS_CONFIG.API_URL) || 'https://script.google.com/macros/s/AKfycbxe1NQ1APDCMdhrp9f7f_TEGYWS4GkCmLnCS87ARFePJDA9WG-Td_8nPQ9r6SNOgr6wdg/exec',
  SHEET_NAME: 'TRAINING_HOURS'
};

let trainingRows = [];
let visibleTrainingRows = [];
let currentTrainingOriginalPayload = null;
let isTrainingSaving = false;

function formatTrainingThaiDate(value) {
  return window.MisThaiDate ? window.MisThaiDate.formatDisplay(value) : String(value || '');
}

function formatTrainingThaiDateInput(value) {
  return window.MisThaiDate ? window.MisThaiDate.formatInput(value) : String(value || '');
}

function trainingThaiDateToIso(value) {
  return window.MisThaiDate ? window.MisThaiDate.toIsoCe(value) : String(value || '');
}

function normalizeTraining(row) {
  row = normalizeRecord(row || {});
  return {
    ...row,
    ROW_INDEX: row.ROW_INDEX || row.rowIndex || '',
    TRAINING_ID: row.TRAINING_ID || row.KEY_ID || row.trainingId || '',
    ORDER_NO: row.ORDER_NO || row['เลขที่คำสั่ง'] || '',
    ORDER_DATE: formatTrainingThaiDate(row.ORDER_DATE || row['วันที่ออกคำสั่ง'] || ''),
    TRAINING_TITLE: row.TRAINING_TITLE || row['หัวข้ออบรม/ดูงาน'] || '',
    TRAINING_LOCATION: row.TRAINING_LOCATION || row['สถานที่อบรม/ดูงาน'] || '',
    TRAINING_TYPE: row.TRAINING_TYPE || row['ประเภทการอบรม'] || '',
    START_DATE: formatTrainingThaiDate(row.START_DATE || row['วันที่เริ่มการอบรม'] || ''),
    END_DATE: formatTrainingThaiDate(row.END_DATE || row['วันที่สิ้นสุดการอบรม'] || ''),
    RETURN_DATE: formatTrainingThaiDate(row.RETURN_DATE || row['วันที่กลับไปปฏิบัติราชการ'] || ''),
    HOURS: row.HOURS || row['จำนวนชั่วโมงที่อบรม'] || '',
    BUDGET_AMOUNT: row.BUDGET_AMOUNT || row['งบประมาณ(บาท)'] || row['งบประมาณ (บาท)'] || '',
    BUDGET_TYPE: row.BUDGET_TYPE || row['ประเภทงบประมาณ'] || '',
    ATTACHMENT_URL: row.ATTACHMENT_URL || row['Upload บันทึกไปอบรม/ดูงาน'] || '',
    YEAR_FISCAL: row.YEAR_FISCAL || row['ปีงบประมาณ'] || row['ปีงบ พ.ศ.'] || row.FISCAL_YEAR_BE || ''
  };
}

async function trainingApi(action, payload = {}) {
  const url = new URL(TRAINING_CONFIG.API_URL);
  url.searchParams.set('action', action);
  url.searchParams.set('system', 'MIS');

  const user = typeof getActiveMisUser === 'function' ? getActiveMisUser() : (Auth.getUser() || {});
  const body = {
    action,
    system: 'MIS',
    token: Auth.getToken(),
    personId: user.personId || '',
    email: user.email || '',
    fullName: user.fullName || '',
    ...payload
  };

  const response = await fetch(url.toString(), {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain;charset=UTF-8' },
    body: JSON.stringify(body)
  });
  const text = await response.text();
  if (!response.ok) {
    return { ok: false, message: getTrainingApiErrorMessage(response.status, text), raw: text };
  }
  try {
    const result = JSON.parse(text);
    const message = result.message || '';
    if (
      !(result.ok === true || result.success === true) &&
      typeof isExpiredSessionMessage === 'function' &&
      isExpiredSessionMessage(message)
    ) {
      if (typeof handleExpiredSession === 'function') handleExpiredSession(message);
    }
    return {
      ...result,
      ok: result.ok === true || result.success === true,
      data: result.data || result.rows || result.items || [],
      message
    };
  } catch (_) {
    return { ok: false, message: getTrainingApiErrorMessage(response.status, text), raw: text };
  }
}

function getTrainingApiErrorMessage(status, text) {
  const preview = String(text || '').trim().slice(0, 180);
  if (/^<!doctype html|^<html[\s>]/i.test(preview)) {
    return 'Training API ไม่ได้ส่ง JSON กลับมา กรุณาตรวจสอบ Apps Script deploy/backend URL';
  }
  return preview
    ? `Training API ตอบกลับผิดรูปแบบ (HTTP ${status || 'unknown'}): ${preview}`
    : `Training API ตอบกลับผิดรูปแบบ (HTTP ${status || 'unknown'})`;
}

function setTrainingAlert(message, type = 'info') {
  const el = document.getElementById('training-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

async function loadTraining() {
  const panel = document.getElementById('training-panel');
  if (panel) panel.hidden = true;
  setTrainingAlert('กำลังโหลดข้อมูลการอบรม...', 'info');

  try {
    const result = await trainingApi('getMyTraining');
    if (!result.ok) {
      setTrainingAlert(result.message || 'โหลดข้อมูลการอบรมไม่สำเร็จ', 'error');
      return;
    }

    trainingRows = Array.isArray(result.data) ? result.data.map(normalizeTraining) : [];
    renderTraining(trainingRows);
    setTrainingAlert('', 'info');
    if (panel) panel.hidden = false;
  } catch (err) {
    console.error(err);
    setTrainingAlert(err.message || 'เชื่อมต่อ Training API ไม่สำเร็จ', 'error');
  }
}

function renderTraining(rows) {
  visibleTrainingRows = Array.isArray(rows) ? [...rows] : [];
  const tbody = document.getElementById('training-tbody');
  const mobile = document.getElementById('training-mobile-cards');
  const total = document.getElementById('training-total-badge');
  const hours = document.getElementById('training-hours-badge');
  const totalHours = visibleTrainingRows.reduce((sum, row) => sum + (parseFloat(row.HOURS) || 0), 0);

  if (total) total.textContent = `${visibleTrainingRows.length} รายการ`;
  if (hours) hours.textContent = `${totalHours.toLocaleString('th-TH')} ชั่วโมง`;
  if (!tbody || !mobile) return;

  if (!visibleTrainingRows.length) {
    tbody.innerHTML = '<tr><td colspan="9" class="research-empty">ยังไม่มีข้อมูลการอบรม</td></tr>';
    mobile.innerHTML = '<div class="research-empty-card">ยังไม่มีข้อมูลการอบรม</div>';
    return;
  }

  tbody.innerHTML = visibleTrainingRows.map((row, index) => {
    const key = escapeHtml(row.TRAINING_ID || '');
    const rowIndex = escapeHtml(row.ROW_INDEX || '');
    const title = displayValue(row.TRAINING_TITLE);
    return `
      <tr>
        <td>${index + 1}</td>
        <td class="research-title-cell">${escapeHtml(title)}</td>
        <td>${escapeHtml(displayValue(row.TRAINING_LOCATION))}</td>
        <td><span class="research-badge soft">${escapeHtml(displayValue(row.TRAINING_TYPE))}</span></td>
        <td>${escapeHtml(displayValue(row.START_DATE))}</td>
        <td>${escapeHtml(displayValue(row.END_DATE))}</td>
        <td>${escapeHtml(formatTrainingHours(row.HOURS))}</td>
        <td>${escapeHtml(formatTrainingBudget(row.BUDGET_AMOUNT))}</td>
        <td>
          <div class="research-row-actions">
            ${renderTrainingAttachmentButton(row)}
            <button class="btn btn-secondary btn-small" type="button" data-training-edit="${key}" data-row-index="${rowIndex}">แก้ไข</button>
            <button class="btn btn-danger btn-small" type="button" data-training-delete="${key}" data-row-index="${rowIndex}" data-title="${escapeHtml(title)}">ลบ</button>
          </div>
        </td>
      </tr>
    `;
  }).join('');

  mobile.innerHTML = visibleTrainingRows.map((row) => {
    const key = escapeHtml(row.TRAINING_ID || '');
    const rowIndex = escapeHtml(row.ROW_INDEX || '');
    return `
      <article class="research-mobile-card">
        <strong>${escapeHtml(displayValue(row.TRAINING_TITLE))}</strong>
        <span>${escapeHtml(displayValue(row.TRAINING_TYPE))} / ${escapeHtml(displayValue(row.START_DATE))}${hasDisplayValue(row.END_DATE) ? ' - ' + escapeHtml(displayValue(row.END_DATE)) : ''} / ${escapeHtml(formatTrainingHours(row.HOURS))}</span>
        <div class="research-row-actions">
          ${renderTrainingAttachmentButton(row)}
          <button class="btn btn-secondary btn-small" type="button" data-training-edit="${key}" data-row-index="${rowIndex}">แก้ไข</button>
          <button class="btn btn-danger btn-small" type="button" data-training-delete="${key}" data-row-index="${rowIndex}" data-title="${escapeHtml(displayValue(row.TRAINING_TITLE))}">ลบ</button>
        </div>
      </article>
    `;
  }).join('');
}

function renderTrainingAttachmentButton(row) {
  const url = String(row?.ATTACHMENT_URL || '').trim();
  if (!url) return '';
  return `<a class="btn btn-secondary btn-small" href="${escapeHtml(url)}" target="_blank" rel="noopener">ดูไฟล์</a>`;
}

function filterTraining() {
  const query = (document.getElementById('training-search-input')?.value || '').trim().toLowerCase();
  if (!query) {
    renderTraining(trainingRows);
    return;
  }
  renderTraining(trainingRows.filter((row) => [
    row.TRAINING_TITLE,
    row.TRAINING_LOCATION,
    row.TRAINING_TYPE,
    row.BUDGET_TYPE,
    row.START_DATE
  ].join(' ').toLowerCase().includes(query)));
}

function openTrainingModal(row) {
  const form = document.getElementById('training-form');
  if (!form) return;
  form.reset();
  setTrainingFormAlert('');
  setTrainingHalfDayMode(false);
  setTrainingCurrentAttachmentLink('');
  document.getElementById('training-form-key-id').value = '';
  document.getElementById('training-form-row-index').value = '';
  currentTrainingOriginalPayload = null;

  if (row) {
    document.getElementById('training-modal-title').textContent = 'แก้ไขข้อมูลการอบรม';
    populateTrainingForm(form, row);
    setTrainingCurrentAttachmentLink(row.ATTACHMENT_URL || '');
    document.getElementById('training-form-key-id').value = row.TRAINING_ID || '';
    document.getElementById('training-form-row-index').value = row.ROW_INDEX || '';
    syncTrainingHalfDayFromCurrentHours();
    currentTrainingOriginalPayload = serializeTrainingForm(form);
  } else {
    document.getElementById('training-modal-title').textContent = 'เพิ่มข้อมูลการอบรม';
    calculateTrainingHoursFromDates();
  }

  openModal('training-modal');
}

function populateTrainingForm(form, row) {
  const dateFields = ['ORDER_DATE', 'START_DATE', 'END_DATE', 'RETURN_DATE'];
  Array.from(form.elements).forEach((el) => {
    if (!el.name) return;
    el.value = dateFields.includes(el.name) ? formatTrainingThaiDateInput(row[el.name]) : row[el.name] || '';
  });
}

function serializeTrainingForm(form) {
  const payload = {};
  const dateFields = ['ORDER_DATE', 'START_DATE', 'END_DATE', 'RETURN_DATE'];
  Array.from(form.elements).forEach((el) => {
    if (!el.name || el.disabled) return;
    if (el.type === 'file') return;
    payload[el.name] = dateFields.includes(el.name) ? trainingThaiDateToIso(el.value) : el.value;
  });
  return payload;
}

function setTrainingCurrentAttachmentLink(url) {
  const hidden = document.getElementById('training-attachment-url');
  const linkText = document.getElementById('training-current-attachment');
  const cleanUrl = String(url || '').trim();
  if (hidden) hidden.value = cleanUrl;
  if (!linkText) return;
  linkText.innerHTML = cleanUrl
    ? `ไฟล์ปัจจุบัน: <a href="${escapeHtml(cleanUrl)}" target="_blank" rel="noopener">เปิดไฟล์</a>`
    : 'ยังไม่มีลิงก์ไฟล์แนบ';
  setTrainingLinkCheckResult('');
}

function setTrainingLinkCheckResult(message, type = '') {
  const el = document.getElementById('training-link-check-result');
  if (!el) return;
  el.textContent = message || '';
  el.className = type || '';
}

function extractTrainingDriveFileId(url) {
  const text = String(url || '').trim();
  if (!text) return '';
  let match = text.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (match) return match[1];
  match = text.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (match) return match[1];
  match = text.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  return match ? match[1] : '';
}

function checkImageLoad(url, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const img = new Image();
    const timer = window.setTimeout(() => {
      img.onload = null;
      img.onerror = null;
      resolve(false);
    }, timeoutMs);
    img.onload = () => {
      window.clearTimeout(timer);
      resolve(true);
    };
    img.onerror = () => {
      window.clearTimeout(timer);
      resolve(false);
    };
    img.src = url;
  });
}

async function checkTrainingAttachmentLink() {
  const url = String(document.getElementById('training-attachment-url')?.value || '').trim();
  if (!url) {
    setTrainingLinkCheckResult('กรุณาวางลิงก์ก่อนตรวจ', 'error');
    return;
  }
  if (!/^https?:\/\//i.test(url)) {
    setTrainingLinkCheckResult('รูปแบบลิงก์ไม่ถูกต้อง', 'error');
    return;
  }
  const fileId = extractTrainingDriveFileId(url);
  if (!fileId) {
    setTrainingLinkCheckResult('ตรวจได้เฉพาะลิงก์ Google Drive แบบมี file id', 'warning');
    return;
  }
  setTrainingLinkCheckResult('กำลังตรวจลิงก์...', '');
  const publicUrl = `https://drive.google.com/thumbnail?id=${encodeURIComponent(fileId)}&sz=w64`;
  const ok = await checkImageLoad(publicUrl);
  setTrainingLinkCheckResult(
    ok
      ? 'ลิงก์นี้น่าจะเปิดแบบสาธารณะได้'
      : 'ยังตรวจ public ไม่ผ่าน ถ้าแชร์เฉพาะ @rumail.ru.ac.th ระบบอาจตรวจไม่ได้ ให้ทดสอบเปิดด้วยบัญชี Rumail',
    ok ? 'success' : 'warning'
  );
}

function showTrainingSaveOverlay(message) {
  let overlay = document.getElementById('training-save-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'training-save-overlay';
    overlay.className = 'save-blocking-overlay hidden';
    overlay.innerHTML = `
      <div class="save-blocking-box">
        <div class="save-blocking-spinner" aria-hidden="true"></div>
        <strong data-save-blocking-message></strong>
      </div>
    `;
    document.body.appendChild(overlay);
  }
  const text = overlay.querySelector('[data-save-blocking-message]');
  if (text) text.textContent = message || 'กำลังบันทึกข้อมูล...';
  overlay.classList.remove('hidden');
  document.body.classList.add('is-save-blocked');
}

function hideTrainingSaveOverlay() {
  const overlay = document.getElementById('training-save-overlay');
  if (overlay) overlay.classList.add('hidden');
  document.body.classList.remove('is-save-blocked');
}

function showTrainingDonePopup(message = 'บันทึกข้อมูลการอบรมเรียบร้อยแล้ว') {
  let popup = document.getElementById('training-done-popup');
  if (!popup) {
    popup = document.createElement('div');
    popup.id = 'training-done-popup';
    popup.className = 'save-done-popup hidden';
    document.body.appendChild(popup);
  }
  popup.textContent = message;
  popup.classList.remove('hidden');
  window.clearTimeout(showTrainingDonePopup.timerId);
  showTrainingDonePopup.timerId = window.setTimeout(() => {
    popup.classList.add('hidden');
  }, 2200);
}

function getChangedTrainingPayload(currentPayload, originalPayload) {
  if (!originalPayload) return { ...currentPayload };

  const changed = {};
  const alwaysKeep = ['TRAINING_ID', 'ROW_INDEX'];
  alwaysKeep.forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(currentPayload, key)) changed[key] = currentPayload[key];
  });

  Object.keys(currentPayload || {}).forEach((key) => {
    if (alwaysKeep.includes(key)) return;
    const current = normalizeTrainingCompareValue(currentPayload[key]);
    const original = normalizeTrainingCompareValue(originalPayload[key]);
    if (current !== original) changed[key] = currentPayload[key];
  });

  return changed;
}

function normalizeTrainingCompareValue(value) {
  return String(value == null ? '' : value).replace(/\r\n/g, '\n').trim();
}

function setTrainingFormAlert(message, type = 'error') {
  const el = document.getElementById('training-form-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

function validateTrainingForm(payload) {
  if (!String(payload.TRAINING_TITLE || '').trim()) return 'กรุณากรอกหัวข้ออบรม/ดูงาน';
  if (!String(payload.HOURS || '').trim()) return 'กรุณากรอกจำนวนชั่วโมงที่อบรม';
  return '';
}

function getTrainingDateValue(id) {
  const value = document.getElementById(id)?.value || '';
  if (!value) return null;
  const isoValue = trainingThaiDateToIso(value);
  if (!isoValue) return null;
  const date = new Date(`${isoValue}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function calculateTrainingHoursFromDates() {
  const halfDay = document.getElementById('training-half-day-checkbox')?.checked;
  const hoursInput = document.getElementById('training-hours-input');
  if (!hoursInput || halfDay) return;

  const start = getTrainingDateValue('training-start-date');
  const end = getTrainingDateValue('training-end-date');
  if (!start || !end || end < start) {
    hoursInput.value = '';
    return;
  }

  const dayCount = Math.floor((end.getTime() - start.getTime()) / 86400000) + 1;
  hoursInput.value = String(dayCount * 7);
}

function setTrainingHalfDayMode(enabled) {
  const checkbox = document.getElementById('training-half-day-checkbox');
  const hoursInput = document.getElementById('training-hours-input');
  if (checkbox) checkbox.checked = Boolean(enabled);
  if (!hoursInput) return;
  hoursInput.readOnly = !enabled;
  hoursInput.classList.toggle('readonly', !enabled);
  if (enabled) {
    hoursInput.value = '';
  } else {
    calculateTrainingHoursFromDates();
  }
}

function syncTrainingHalfDayFromCurrentHours() {
  const hoursInput = document.getElementById('training-hours-input');
  const start = getTrainingDateValue('training-start-date');
  const end = getTrainingDateValue('training-end-date');
  const hours = parseFloat(hoursInput?.value || '');
  if (!hoursInput || !start || !end || Number.isNaN(hours) || end < start) {
    setTrainingHalfDayMode(false);
    return;
  }

  const dayCount = Math.floor((end.getTime() - start.getTime()) / 86400000) + 1;
  const expected = dayCount * 7;
  setTrainingHalfDayMode(hours !== expected);
  if (hours === expected) hoursInput.value = String(expected);
}

async function saveTraining(event) {
  event?.preventDefault();
  event?.stopPropagation();
  if (isTrainingSaving) return;
  const form = document.getElementById('training-form');
  const button = document.getElementById('training-save-btn');
  if (!form) return;

  const payload = serializeTrainingForm(form);
  const validation = validateTrainingForm(payload);
  if (validation) {
    setTrainingFormAlert(validation, 'error');
    return;
  }
  const action = payload.TRAINING_ID || payload.ROW_INDEX ? 'updateTraining' : 'createTraining';
  const payloadForSave = action === 'updateTraining'
    ? getChangedTrainingPayload(payload, currentTrainingOriginalPayload)
    : { ...payload };

  if (
    action === 'updateTraining' &&
    Object.keys(payloadForSave).filter((key) => !['TRAINING_ID', 'ROW_INDEX'].includes(key)).length === 0
  ) {
    setTrainingFormAlert('ยังไม่มีข้อมูลที่เปลี่ยนแปลง', 'info');
    return;
  }

  isTrainingSaving = true;
  setButtonLoading(button, true, 'กำลังบันทึก...');
  showTrainingSaveOverlay('กำลังบันทึกข้อมูล...');
  setTrainingFormAlert('', 'error');

  try {
    const result = await trainingApi(action, payloadForSave);
    if (!result.ok) {
      setTrainingFormAlert(result.message || 'บันทึกข้อมูลการอบรมไม่สำเร็จ', 'error');
      return;
    }
    closeModal('training-modal');
    showTrainingDonePopup(result.message || 'บันทึกข้อมูลการอบรมเรียบร้อยแล้ว');
    setTrainingAlert(result.message || 'บันทึกข้อมูลการอบรมเรียบร้อยแล้ว', 'info');
    await loadTraining();
  } catch (err) {
    console.error(err);
    setTrainingFormAlert(err.message || 'เชื่อมต่อ Training API ไม่สำเร็จ', 'error');
  } finally {
    isTrainingSaving = false;
    setButtonLoading(button, false);
    hideTrainingSaveOverlay();
  }
}

async function deleteTrainingByKey(key, rowIndex, title) {
  if (!window.confirm(`ต้องการลบ "${title || 'ข้อมูลการอบรมนี้'}" ใช่หรือไม่?`)) return;
  try {
    const result = await trainingApi('deleteTraining', { TRAINING_ID: key || '', ROW_INDEX: rowIndex || '' });
    if (!result.ok) {
      setTrainingAlert(result.message || 'ลบข้อมูลการอบรมไม่สำเร็จ', 'error');
      return;
    }
    await loadTraining();
  } catch (err) {
    console.error(err);
    setTrainingAlert(err.message || 'เชื่อมต่อ Training API ไม่สำเร็จ', 'error');
  }
}

function formatTrainingHours(value) {
  if (!hasDisplayValue(value)) return '-';
  const num = parseFloat(value);
  return Number.isNaN(num) ? String(value) : `${num.toLocaleString('th-TH')} ชม.`;
}

function formatTrainingBudget(value) {
  if (!hasDisplayValue(value)) return '-';
  const num = parseFloat(value);
  return Number.isNaN(num) ? String(value) : `${num.toLocaleString('th-TH')} บาท`;
}

function exportTraining() {
  const rows = visibleTrainingRows.length ? visibleTrainingRows : trainingRows;
  if (!rows.length) {
    setTrainingAlert('ยังไม่มีข้อมูลสำหรับ export', 'error');
    return;
  }
  const win = window.open('', '_blank');
  if (!win) {
    window.print();
    return;
  }
  win.document.write(`
    <html><head><title>รายงานสรุปชั่วโมงอบรม</title><style>
      body{font-family:Sarabun,Arial,sans-serif;padding:28px;color:#16283d}
      table{width:100%;border-collapse:collapse}th,td{border:1px solid #dbe4f0;padding:8px;text-align:left;vertical-align:top}
      th{background:#f3f7ff}
    </style></head><body>
      <h1>รายงานสรุปชั่วโมงอบรม</h1>
      <p>จำนวน ${rows.length} รายการ</p>
      <table><thead><tr><th>#</th><th>หัวข้อ</th><th>สถานที่</th><th>ประเภท</th><th>วันที่เริ่ม</th><th>ชั่วโมง</th></tr></thead><tbody>
      ${rows.map((row, index) => `<tr><td>${index + 1}</td><td>${escapeHtml(displayValue(row.TRAINING_TITLE))}</td><td>${escapeHtml(displayValue(row.TRAINING_LOCATION))}</td><td>${escapeHtml(displayValue(row.TRAINING_TYPE))}</td><td>${escapeHtml(displayValue(row.START_DATE))}</td><td>${escapeHtml(formatTrainingHours(row.HOURS))}</td></tr>`).join('')}
      </tbody></table>
    </body></html>
  `);
  win.document.close();
  win.print();
}

function initTrainingModule() {
  window.MisThaiDate?.init(document.getElementById('training-modal') || document);
  document.getElementById('training-add-btn')?.addEventListener('click', () => openTrainingModal(null));
  document.getElementById('training-export-btn')?.addEventListener('click', exportTraining);
  document.getElementById('training-search-input')?.addEventListener('input', filterTraining);
  document.getElementById('training-form')?.addEventListener('submit', saveTraining);
  document.getElementById('training-attachment-url')?.addEventListener('input', (event) => {
    setTrainingCurrentAttachmentLink(event.target.value || '');
  });
  document.getElementById('training-check-link-btn')?.addEventListener('click', checkTrainingAttachmentLink);
  document.getElementById('training-start-date')?.addEventListener('change', calculateTrainingHoursFromDates);
  document.getElementById('training-end-date')?.addEventListener('change', calculateTrainingHoursFromDates);
  document.getElementById('training-half-day-checkbox')?.addEventListener('change', (event) => {
    setTrainingHalfDayMode(event.target.checked);
  });

  document.addEventListener('click', (event) => {
    const editButton = event.target.closest('[data-training-edit]');
    if (editButton) {
      const key = editButton.getAttribute('data-training-edit') || '';
      const rowIndex = editButton.getAttribute('data-row-index') || '';
      const row = trainingRows.find((item) =>
        String(item.TRAINING_ID || '') === key ||
        String(item.ROW_INDEX || '') === rowIndex
      );
      if (row) openTrainingModal(row);
      return;
    }

    const deleteButton = event.target.closest('[data-training-delete]');
    if (deleteButton) {
      deleteTrainingByKey(
        deleteButton.getAttribute('data-training-delete') || '',
        deleteButton.getAttribute('data-row-index') || '',
        deleteButton.getAttribute('data-title') || ''
      );
    }
  });
}
